"""Generate the W5.5 PL5 golden fixtures (EV-PL-004 instructions, EV-PL-005 quota).

Deterministic, hermetic, synthetic. Student text is invented; no names, emails
that could be real (example.com only), no keys. Re-run to regenerate exactly
the same bytes; a fixture edit must go through this script (or a reviewed
hand edit) so the README inventory never drifts.

Usage: python scripts/gen_pl5_goldens.py [--check]
  --check  exit 1 when the on-disk fixtures differ from the generated bytes.
"""

from __future__ import annotations

import argparse
import json
from pathlib import Path

