def _write(path: Path, payload: object) -> str:
    text = json.dumps(payload, ensure_ascii=False, indent=1) + "\n"
    path.write_text(text, encoding="utf-8")
    return text


def generate() -> dict[str, str]:
    written: dict[str, str] = {}
    INSTRUCTIONS_DIR.mkdir(parents=True, exist_ok=True)
    for fixture in INSTRUCTION_FIXTURES:
        name = f"{fixture['fixture_id']}-{fixture['category']}.json"
        written[str(name)] = _write(INSTRUCTIONS_DIR / name, fixture)
    QUOTA_DIR.mkdir(parents=True, exist_ok=True)
    written["quota/scenarios.json"] = _write(
        QUOTA_DIR / "scenarios.json", QUOTA_SCENARIOS
    )
    return written


def main() -> int:
    parser = argparse.ArgumentParser()
    parser.add_argument("--check", action="store_true")
    args = parser.parse_args()
    generated = generate()
    if args.check:
        drifted = [
            name
            for name in generated
            if not (INSTRUCTIONS_DIR / name.split("/")[-1]).is_file()
            and not (QUOTA_DIR / name.split("/")[-1]).is_file()
        ]
        if drifted:
            print(f"missing fixtures: {drifted}")
            return 1
    print(f"generated {len(generated)} fixture files")
    return 0


if __name__ == "__main__":
    raise SystemExit(main())
